package com.bank.approval;

import java.math.BigDecimal;
import java.util.logging.*;

public class ApprovalDemo {

    private static final Logger log = Logger.getLogger(ApprovalDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build the chain: Clerk -> Officer -> Manager
        ApprovalHandler clerk = new ClerkApprover();
        ApprovalHandler officer = new OfficerApprover();
        ApprovalHandler manager = new ManagerApprover();
        clerk.setNext(officer);
        officer.setNext(manager);

        log.info("=== National Bank of India — Transfer Approval Chain ===");

        // Scenario 1: Rajesh transfers 12 lakh -> escalates to Manager
        TransferRequest big = new TransferRequest("SAV2001", "CUR3001", new BigDecimal("1200000"));
        log.info(() -> "Submitting transfer of Rs." + big.getAmount() + " from " + big.getFromId());
        clerk.approve(big);

        // Scenario 2: Priya transfers 40,000 -> handled by Clerk
        TransferRequest small = new TransferRequest("CUR3001", "SAV2001", new BigDecimal("40000"));
        log.info(() -> "Submitting transfer of Rs." + small.getAmount() + " from " + small.getFromId());
        clerk.approve(small);

        // Scenario 3: 25 lakh exceeds every limit -> terminal reject
        TransferRequest huge = new TransferRequest("SAV2001", "CUR3001", new BigDecimal("2500000"));
        log.info(() -> "Submitting transfer of Rs." + huge.getAmount() + " from " + huge.getFromId());
        clerk.approve(huge);
    }
}

// ─── Would be in model/TransferRequest.java ───
class TransferRequest {
    private final String fromId;
    private final String toId;
    private final BigDecimal amount;

    TransferRequest(String fromId, String toId, BigDecimal amount) {
        this.fromId = fromId;
        this.toId = toId;
        this.amount = amount;
    }
    String getFromId() { return fromId; }
    String getToId() { return toId; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in handler/ApprovalHandler.java ───
abstract class ApprovalHandler {
    private static final Logger log = Logger.getLogger(ApprovalHandler.class.getName());
    protected ApprovalHandler next;
    protected final BigDecimal limit;
    protected final String role;

    ApprovalHandler(String role, BigDecimal limit) {
        this.role = role;
        this.limit = limit;
    }

    void setNext(ApprovalHandler next) { this.next = next; }

    // Core Chain of Responsibility method
    void approve(TransferRequest request) {
        if (request.getAmount().compareTo(limit) <= 0) {
            log.info(() -> role + " APPROVED transfer of Rs." + request.getAmount()
                    + " (within limit Rs." + limit + ")");
        } else if (next != null) {
            log.warning(() -> role + " cannot approve Rs." + request.getAmount()
                    + " (limit Rs." + limit + "). Escalating to " + next.role + ".");
            next.approve(request);
        } else {
            log.severe(() -> "No handler can approve Rs." + request.getAmount()
                    + ". Transfer REJECTED — manual review required.");
        }
    }
}

// ─── Would be in handler/ClerkApprover.java ───
class ClerkApprover extends ApprovalHandler {
    ClerkApprover() { super("Clerk", new BigDecimal("50000")); }
}

// ─── Would be in handler/OfficerApprover.java ───
class OfficerApprover extends ApprovalHandler {
    OfficerApprover() { super("Officer", new BigDecimal("500000")); }
}

// ─── Would be in handler/ManagerApprover.java ───
class ManagerApprover extends ApprovalHandler {
    ManagerApprover() { super("Manager", new BigDecimal("2000000")); }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel(),
                formatMessage(record));
    }
}
